import { css, html, nothing, svg, type TemplateResult } from 'lit';
import { field, rnd, type Scene, type Visitor } from './types';

/**
 * The reef: a Ningaloo coral garden seen from under the water, drawn as a field guide would draw it.
 * Always there: slanting light from wherever the sun is, shimmer along the surface, kelp, coral, an anemone and a giant clam at the edges,
 * bubble threads up the margins, plankton at two depths and a far school that turns together. Evening and night: fewer shafts,
 * glowing plankton and moon-jellies. The cast swims through the open band at the top or potters about in the bottom corners.
 * Light comes from above, so every animal is darker on the back and pale underneath.
 */

type T = TemplateResult;
/** a top-to-bottom (or any) two- or three-tone gradient */
const lg = (id: string, a: string, b: string, x2 = 0, y2 = 1, mid = ''): T => svg`<linearGradient id=${id} x2=${x2} y2=${y2}><stop stop-color=${a}/>${mid ? svg`<stop offset=".5" stop-color=${mid}/>` : nothing}<stop offset="1" stop-color=${b}/></linearGradient>`;
const rg = (id: string, a: string, b: string, cx = 0.5, cy = 0.4, r = 0.7): T => svg`<radialGradient id=${id} cx=${cx} cy=${cy} r=${r}><stop stop-color=${a}/><stop offset="1" stop-color=${b}/></radialGradient>`;
/** a real eye: dark, with a thin iris ring and one small catch-light */
const eye = (x: number, y: number, r = 2, ring = '#c9b27a'): T => svg`<circle cx=${x} cy=${y} r=${r} fill="#16181b" stroke=${ring} stroke-width=${r * 0.36}/><circle cx=${x - r * 0.3} cy=${y - r * 0.36} r=${r * 0.3} fill="#fff" opacity=".85"/>`;
const at = (x: number, y: number, s: number, c: T | T[], sx = 1): T => svg`<g transform="translate(${x} ${y}) scale(${s * sx} ${s})">${c}</g>`;
/** a reef fish facing right, 40 long and 20 deep, nose at (40,10): countershaded body, forked tail that beats, fins, gill line and eye */
const rf = (id: string, back: string, belly: string, fin: string, o: { stripe?: string; tail?: string; d?: string; extra?: T } = {}): T => svg`${lg(id, back, belly)}
  <path class=${o.d === '' ? '' : 'reef-wa'} style="transform-origin:100% 50%;--r:17deg;--d:${o.d ?? '.33s'}" d="M11 10L1 2Q4.5 10 1 18Z" fill=${o.tail ?? fin}/>
  <path d="M30 3.2Q24-2.6 15 5.5ZM25 17Q21 22.6 15 15.5Z" fill=${fin} opacity=".9"/>
  <path d="M40 10C36 4 28 1.6 22 2.6C16 3.6 12 7 9.5 9L9.5 11C12 13 16 16.4 22 17.4C28 18.4 36 16 40 10Z" fill="url(#${id})"/>
  ${o.stripe ? svg`<path d="M37 9Q24 5.4 10 9.5L10 10.7Q24 8.6 37 10.5Z" fill=${o.stripe}/>` : nothing}
  <path d="M38 11.6Q28 16.6 12 11.6Q24 19.4 38 11.6Z" fill="#fff" opacity=".3"/><path d="M31.5 5.6Q29.6 10 31.5 14.8" stroke="#000" stroke-opacity=".2" stroke-width=".8" fill="none"/>
  <path d="M29 10.6q-6 .5-8 5q6 .5 9-2.5z" fill=${fin} opacity=".75"/>${eye(35, 8.4, 1.7)}${o.extra ?? nothing}`;
const bub = (x: number, y: number, r: number, style: string): T => svg`<circle class="reef-bub" style=${style} cx=${x} cy=${y} r=${r} fill="rgba(255,255,255,.12)" stroke="rgba(255,255,255,.85)" stroke-width=${Math.max(1, r * 0.3)}/>`;

