const SH = 'M10 4q8-4 12 4l8 3v3l-9 1q2 6-2 10q8 8 2 18q-4 8-12 6q-6-2-4-8q2-4 6-2q2 2 0 4q4 0 5-5q2-8-6-14q-8-8-4-20z';
const horse = (id: string, x: number, y: number, s: number, a: string, b: string, dark: string): T => at(x, y, s, svg`${lg(id, a, b, 1, 0)}<path d="M8 5L4 0l8 3zM7 9l-5-2 4 5z" fill=${dark}/><path class="reef-wa" style="transform-origin:100% 50%;--r:14deg;--d:.21s" d="M11 25q-9 1-9 8q7 2 10-3z" fill=${a} opacity=".8"/><path d=${SH} fill="url(#${id})"/><path d="M12 15l8 1M11 20l9 1M12 25l9 2M14 30l9 1M17 35l7 0M18 40l5-1M15 45l5 0" stroke=${dark} stroke-width="1" opacity=".65"/><path d="M11 6q6-2 9 3" stroke="#fff" stroke-width="1.4" fill="none" opacity=".35"/>${eye(17, 9, 1.9, '#e9d28a')}`);
const SD = 'M128 30q-9-2-13 5q-5 11-20 13q-16 2-25 11q-10 9-26 8q-13-1-24 4';
const leaf = (x: number, y: number, a: number, s = 1): T => svg`<g transform="translate(${x} ${y}) rotate(${a}) scale(${s})"><path d="M0 0L-1-8" stroke="#8c7a2a" stroke-width="1.3"/><path d="M-1-7C-10-10-11-22-5-30C-2-27 1-28 3-32C8-24 7-12-1-7Z" fill="url(#rsdL)"/><path d="M-1-8Q-2-19-1-29M-1-14l-5-5M-1-18l4-5" stroke="#6f6a22" stroke-width=".7" fill="none" opacity=".7"/></g>`;
