const hermitEyes = (x: number, y: number): T => at(x, y, 1, svg`<path d="M0 0L-1-9M6 0L8-8" stroke="#d9603a" stroke-width="1.8" stroke-linecap="round"/><ellipse cx="-1" cy="-10" rx="1.7" ry="2.2" fill="#15171a"/><ellipse cx="8.2" cy="-9" rx="1.7" ry="2.2" fill="#15171a"/><circle cx="-1.5" cy="-10.8" r=".6" fill="#fff"/><circle cx="7.7" cy="-9.8" r=".6" fill="#fff"/>`);
const hump = (id: string): T => svg`${lg(id, '#2c4658', '#57768a')}<g class="reef-wa" style="transform-origin:100% 50%;--r:8deg;--d:3.7s"><path d="M78 53L58 57L78 67Z" fill="#35536a"/><path d="M62 58C50 46 34 40 16 42C26 48 30 54 30 60C28 68 20 76 12 82C30 82 50 74 62 62Z" fill="#2c4658"/><path d="M30 60q14-2 30 0" stroke="#fff" stroke-opacity=".12" stroke-width="2" fill="none"/></g><path d="M286 56C284 44 262 36 226 34C180 32 120 40 76 54C74 58 74 62 76 66C120 78 190 84 240 78C268 74 286 68 286 56Z" fill="url(#${id})"/><path d="M286 60C270 76 222 84 172 80C212 76 252 70 286 60Z" fill="#d3dfe5" opacity=".85"/><path d="M280 64Q240 76 190 77M276 68Q244 78 206 79M284 60Q250 70 200 73" stroke="#7f98a6" stroke-width=".9" fill="none"/><path d="M132 43q7-9 15-4l4 5z" fill="#2c4658"/><path d="M268 44h.1M260 41h.1M274 49h.1M252 39h.1M266 50h.1" stroke="#4d6b7f" stroke-width="3" stroke-linecap="round"/><path d="M110 46Q180 34 250 38" stroke="#fff" stroke-opacity=".14" stroke-width="4" fill="none" stroke-linecap="round"/>${eye(256, 56, 1.8, '#3a556a')}<g class="reef-wa" style="transform-origin:95% 0;--r:6deg;--d:4.3s"><path d="M214 68C208 92 188 108 160 113C157 106 168 98 178 86C184 78 190 70 198 65Z" fill="#dbe5ea"/><path d="M212 70C204 90 186 104 162 110" stroke="#9fb3bf" stroke-width="1.2" fill="none"/><path d="M214 68q-10-2-16-3" stroke="#35536a" stroke-width="2.4" fill="none"/></g>`;
const dolphin = (id: string, a: string, b: string): T => svg`${lg(id, a, b, 0, 1, a)}<g class="reef-wa" style="transform-origin:100% 40%;--r:13deg;--d:.62s"><path d="M26 24L14 28L24 34Z" fill=${a}/><path d="M16 29C10 22 4 20-4 21C2 25 3 28 2 31C0 36-2 40-6 44C4 43 12 38 16 32Z" fill=${a}/></g><path d="M112 23C108 21 104 20 100 20C96 14 88 10 76 9C72 9 68 9 64 10C60 4 54 1 46 0C50 5 50 9 48 12C34 16 22 22 14 28L24 33C40 38 60 38 76 34C92 30 104 27 112 23Z" fill="url(#${id})"/><path d="M24 33C40 38 60 38 76 34C90 30 102 27 110 24C92 27 60 33 24 33Z" fill="#eef3f6" opacity=".9"/><path d="M40 16Q64 8 96 19" stroke="#fff" stroke-opacity=".2" stroke-width="3" fill="none" stroke-linecap="round"/><path class="reef-wa" style="transform-origin:100% 0;--r:9deg;--d:1.24s" d="M72 33C70 42 64 48 56 49C58 43 60 37 64 32Z" fill=${a}/><path d="M112 23q-7 2-12 1" stroke="#22323f" stroke-width=".8" fill="none"/>${eye(93, 20.5, 1.4, '#3d5263')}`;
const SCHOOL = ((r) => Array.from({ length: 17 }, () => `M${(12 + r() * 104).toFixed(0)} ${(4 + r() * 46).toFixed(0)}q-4-3.6-9 0l-4-3q1.5 3 0 6l4-3q5 3.6 9 0z`).join(''))(rnd(11));
const stalk = (h: number, a: string, b: string): T => { const n = Math.floor(h / 44); return svg`<path d="M20 ${h}${'q-15-22 0-44t0-44'.repeat(n / 2)}" stroke=${a} stroke-width="5.5" stroke-linecap="round" fill="none"/><path d="M19 ${h}${'q-15-22 0-44t0-44'.repeat(n / 2)}" stroke="#fff" stroke-opacity=".14" stroke-width="1.6" fill="none"/>${Array.from({ length: n }, (_, i) => { const l = i % 2 === 0, x = l ? 12 : 28, y = h - 22 - i * 44; return svg`<g transform="translate(${x} ${y}) rotate(${l ? -38 : 38})"><path d="M0 0Q${l ? -7 : 7}-14 0-27Q${l ? 5 : -5}-13 0 0Z" fill=${b}/><circle r="2.6" fill=${a}/></g>`; })}`; };
const spikes = Array.from({ length: 16 }, (_, i) => { const t = (i / 16) * Math.PI * 2 + 0.2, c = Math.cos(t), s = Math.sin(t); return `M${(48 + 24 * c).toFixed(1)} ${(38 + 13 * s).toFixed(1)}L${(48 + 29 * c).toFixed(1)} ${(38 + 15.8 * s).toFixed(1)}`; }).join('') + 'M40 32l-2-3M52 31l1-3M46 40l-1 3M58 37l3 1M36 38l-3 1M56 43l2 2M42 45l-1 3';
